-- 真实公司组织重置脚本：27个组织节点，108个测试账号；不自动执行。
-- 执行前停止应用并备份数据库；在已选中的项目数据库中整份执行（MySQL 8.0+）。
-- 旧部门物理删除重建；旧账号保留ID并停用；admin保留原密码；新测试账号密码123456。
-- 配置、账号和组织同一事务提交；失败回滚。DDL创建备份表/过程本身不属于业务事务。
-- 教科研中心按已确认的直管关系直属院领导，下设科研组、教研组、媒体组。
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS orgsql_rebuild_backups (
  batch_key VARCHAR(100) PRIMARY KEY, captured_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), data JSON NOT NULL
);
DELIMITER $$
DROP PROCEDURE IF EXISTS orgsql_rebuild_20261023$$
CREATE PROCEDURE orgsql_rebuild_20261023()
BEGIN
  DECLARE v_config JSON;
  DECLARE v_draft JSON;
  DECLARE v_old_config JSON;
  DECLARE v_old_draft JSON;
  DECLARE v_depts JSON;
  DECLARE v_new_users JSON;
  DECLARE v_passwords JSON;
  DECLARE v_role_seeds JSON;
  DECLARE v_roles JSON;
  DECLARE v_users JSON;
  DECLARE v_all_pages JSON;
  DECLARE v_business_pages JSON;
  DECLARE v_item JSON;
  DECLARE v_template JSON;
  DECLARE v_type_ids JSON;
  DECLARE v_admin_id VARCHAR(80);
  DECLARE v_id VARCHAR(80);
  DECLARE v_version INT;
  DECLARE v_template_version INT;
  DECLARE v_i INT DEFAULT 0;
  DECLARE v_count INT DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  START TRANSACTION;
  IF EXISTS(SELECT 1 FROM schema_migrations WHERE version=6) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='第六版主数据升级后禁止执行旧整包重置SQL'; END IF;
  SELECT published,draft INTO v_config,v_draft FROM configuration WHERE id='company' FOR UPDATE;
  IF v_config IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='项目尚未初始化，请先执行 db:init'; END IF;
  SET v_old_config=v_config;
  SET v_old_draft=v_draft;
  SELECT COUNT(*),MAX(id) INTO v_count,v_admin_id FROM members WHERE username='admin';
  IF v_count<>1 OR NOT EXISTS(SELECT 1 FROM JSON_TABLE(v_config,'$.users[*]' COLUMNS(id VARCHAR(80) PATH '$.id', username VARCHAR(50) PATH '$.username')) u WHERE u.id=v_admin_id AND u.username='admin') THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='未找到配置与成员表一致的admin，停止重置';
  END IF;
  SELECT id INTO v_id FROM template_catalog_lock WHERE id='catalog' FOR UPDATE;
  IF v_id IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='模板结构未就绪，请先执行 db:migrate'; END IF;
  IF (SELECT COUNT(*) FROM schema_migrations WHERE version IN(2,3,4,5))<>4 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='必须先完成第2、3、4、5版迁移';
  END IF;

  SET v_depts=CONVERT( USING utf8mb4);
  SET v_new_users=CONVERT( USING utf8mb4);
  SET v_passwords=CONVERT( USING utf8mb4);
  SET v_role_seeds=CONVERT( USING utf8mb4);
  SET v_template=CONVERT( USING utf8mb4);

  -- 固定ID仅用于本脚本；若与非本脚本账号冲突则停止，避免覆盖无关人员。
  IF EXISTS(SELECT 1 FROM members m JOIN JSON_TABLE(v_new_users,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id', username VARCHAR(50) PATH '$.username')) n ON m.id=n.id WHERE m.username<>n.username) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='新账号固定ID与既有成员冲突，停止重置';
  END IF;
  -- 指定旧人员的敏感字段授权不能静默放宽，请先在配置中心改为有效角色授权。
  SET v_i=0;
  WHILE v_i<JSON_LENGTH(JSON_EXTRACT(v_config,'$.users')) DO
    SET v_item=JSON_EXTRACT(v_config,CONCAT('$.users[',v_i,']'));
    SET v_id=JSON_UNQUOTE(JSON_EXTRACT(v_item,'$.id'));
    IF v_id<>v_admin_id AND NOT EXISTS(SELECT 1 FROM JSON_TABLE(v_new_users,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id')) n WHERE n.id=v_id)
       AND (JSON_SEARCH(JSON_EXTRACT(v_config,'$.form'),'one',v_id,NULL,'$**.userIds[*]') IS NOT NULL OR JSON_SEARCH(JSON_EXTRACT(v_draft,'$.form'),'one',v_id,NULL,'$**.userIds[*]') IS NOT NULL) THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='表单敏感授权仍绑定旧人员，请先改为角色授权再重置';
    END IF;
    SET v_i=v_i+1;
  END WHILE;

  -- 首次备份保留原始状态；重复执行不会覆盖首次备份，不包含会话令牌。
  INSERT IGNORE INTO orgsql_rebuild_backups(batch_key,data)
  SELECT 'real-org-20261023-v1',JSON_OBJECT(
    'configuration',JSON_OBJECT('published',v_config,'draft',v_draft,'revision',c.revision,'draft_revision',c.draft_revision),
    'departments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',id,'parent_id',parent_id,'name',name,'manager_id',manager_id,'active',active,'data',data)) FROM departments),JSON_ARRAY()),
    'members',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',id,'username',username,'name',name,'department_id',department_id,'active',active,'roles',roles,'password_hash',password_hash)) FROM members),JSON_ARRAY()),
    'roles',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',id,'name',name,'data',data)) FROM roles),JSON_ARRAY())
  ) FROM configuration c WHERE c.id='company';

  -- 新角色绑定当前启用的页面；具体菜单仍由动作权限和页面权限共同过滤。
  SELECT COALESCE(JSON_ARRAYAGG(p.id),JSON_ARRAY()) INTO v_all_pages
  FROM JSON_TABLE(v_config,'$.pages[*]' COLUMNS(id VARCHAR(80) PATH '$.id',enabled INT PATH '$.active')) p WHERE p.enabled=1;
  SELECT COALESCE(JSON_ARRAYAGG(p.id),JSON_ARRAY()) INTO v_business_pages
  FROM JSON_TABLE(v_config,'$.pages[*]' COLUMNS(id VARCHAR(80) PATH '$.id',component VARCHAR(80) PATH '$.component',enabled INT PATH '$.active')) p WHERE p.enabled=1 AND p.component<>'config_overview';
  SET v_roles=JSON_ARRAY();
  SET v_i=0;
  WHILE v_i<JSON_LENGTH(JSON_EXTRACT(v_config,'$.roles')) DO
    SET v_item=JSON_EXTRACT(v_config,CONCAT('$.roles[',v_i,']'));
    IF JSON_UNQUOTE(JSON_EXTRACT(v_item,'$.id')) NOT LIKE 'orgsql-%' THEN SET v_roles=JSON_ARRAY_APPEND(v_roles,'$',v_item); END IF;
    SET v_i=v_i+1;
  END WHILE;
  SET v_i=0;
  WHILE v_i<JSON_LENGTH(v_role_seeds) DO
    SET v_item=JSON_EXTRACT(v_role_seeds,CONCAT('$[',v_i,']'));
    IF JSON_UNQUOTE(JSON_EXTRACT(v_item,'$.id'))='orgsql-admin' THEN
      SET v_item=JSON_SET(v_item,'$.pages',v_all_pages);
    ELSE
      SET v_item=JSON_SET(v_item,'$.pages',v_business_pages);
    END IF;
    SET v_roles=JSON_ARRAY_APPEND(v_roles,'$',v_item);
    SET v_i=v_i+1;
  END WHILE;

  -- 保留旧账号标识与姓名供历史追溯，取消登录资格并释放旧用户名。
  SET v_users=JSON_ARRAY();
  SET v_i=0;
  WHILE v_i<JSON_LENGTH(JSON_EXTRACT(v_config,'$.users')) DO
    SET v_item=JSON_EXTRACT(v_config,CONCAT('$.users[',v_i,']'));
    SET v_id=JSON_UNQUOTE(JSON_EXTRACT(v_item,'$.id'));
    IF v_id=v_admin_id THEN
      SET v_item=JSON_SET(v_item,'$.active',CAST('true' AS JSON),'$.department','company','$.roles',JSON_ARRAY('orgsql-admin'));
      SET v_users=JSON_ARRAY_APPEND(v_users,'$',v_item);
    ELSEIF NOT EXISTS(SELECT 1 FROM JSON_TABLE(v_new_users,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id')) n WHERE n.id=v_id) THEN
      SET v_item=JSON_SET(v_item,'$.active',CAST('false' AS JSON),'$.department','company','$.username',CONCAT('old_',LEFT(SHA2(v_id,256),24)));
      SET v_users=JSON_ARRAY_APPEND(v_users,'$',v_item);
    END IF;
    SET v_i=v_i+1;
  END WHILE;
  SET v_users=JSON_MERGE_PRESERVE(v_users,v_new_users);
  SELECT GREATEST(COALESCE(MAX(version),0),CAST(JSON_UNQUOTE(JSON_EXTRACT(v_config,'$.version')) AS UNSIGNED))+1 INTO v_version FROM configuration_releases;
  SET v_config=JSON_SET(v_config,'$.version',v_version,'$.departments',v_depts,'$.users',v_users,'$.roles',v_roles,'$.workflow',CAST(CONVERT( USING utf8mb4) AS JSON));
  -- 组织重置同时覆盖草稿组织和角色；当前草稿表单沿用原草稿。
  -- 为避免新角色引用不存在的草稿页面，菜单与分组也同步到当前已发布状态；原草稿完整保存在备份中。
  SET v_draft=JSON_SET(v_draft,'$.version',v_version,'$.departments',v_depts,'$.users',v_users,'$.roles',v_roles,'$.workflow',JSON_EXTRACT(v_config,'$.workflow'),'$.pages',JSON_EXTRACT(v_config,'$.pages'),'$.groups',JSON_EXTRACT(v_config,'$.groups'));
  IF JSON_LENGTH(v_depts)>200 OR JSON_LENGTH(v_users)>1000 OR JSON_LENGTH(v_roles)>100 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='重置后的组织、成员或角色超出系统容量'; END IF;

  DELETE FROM sessions;
  UPDATE members SET active=FALSE,department_id='company',username=CONCAT('old_',LEFT(SHA2(id,256),24)) WHERE id<>v_admin_id;
  DELETE FROM departments;
  INSERT INTO departments(id,parent_id,name,manager_id,active,data)
  SELECT d.id,d.parent,d.name,d.manager,TRUE,JSON_OBJECT('id',d.id,'parent',d.parent,'name',d.name,'manager',d.manager,'active',CAST('true' AS JSON))
  FROM JSON_TABLE(v_depts,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id',parent VARCHAR(80) PATH '$.parent',name VARCHAR(80) PATH '$.name',manager VARCHAR(80) PATH '$.manager')) d;
  INSERT INTO roles(id,name,data)
  SELECT r.id,r.name,r.data FROM JSON_TABLE(v_roles,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id',name VARCHAR(80) PATH '$.name',data JSON PATH '$')) r
  ON DUPLICATE KEY UPDATE name=VALUES(name),data=VALUES(data);
  UPDATE members SET department_id='company',active=TRUE,roles=JSON_ARRAY('orgsql-admin') WHERE id=v_admin_id;
  -- 密码由Node scrypt预生成随机盐哈希，不能用MD5/SHA2替代登录密码算法。
  INSERT INTO members(id,username,name,department_id,active,roles,password_hash)
  SELECT u.id,u.username,u.name,u.department,TRUE,u.roles,h.password_hash
  FROM JSON_TABLE(v_new_users,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id',username VARCHAR(50) PATH '$.username',name VARCHAR(80) PATH '$.name',department VARCHAR(80) PATH '$.department',roles JSON PATH '$.roles')) u
  JOIN JSON_TABLE(v_passwords,'$[*]' COLUMNS(id VARCHAR(80) PATH '$.id',password_hash VARCHAR(300) PATH '$.passwordHash')) h ON h.id=u.id
  ON DUPLICATE KEY UPDATE username=VALUES(username),name=VALUES(name),department_id=VALUES(department_id),active=TRUE,roles=VALUES(roles),password_hash=VALUES(password_hash);
  UPDATE configuration SET published=v_config,draft=v_draft,revision=revision+1,draft_revision=draft_revision+1 WHERE id='company';
  INSERT INTO configuration_releases(version,data,actor) VALUES(v_version,v_config,v_admin_id);

  -- 附带一个新组织专用跨部门测试模板；既有模板和发布历史不改写。
  SELECT COALESCE(JSON_ARRAYAGG(id),JSON_ARRAY()) INTO v_type_ids FROM activity_types WHERE active=TRUE;
  IF JSON_LENGTH(v_type_ids)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='没有启用的活动类型，停止重置'; END IF;
  SET v_template=JSON_SET(v_template,'$.activityTypeIds',v_type_ids);
  IF EXISTS(SELECT 1 FROM workflow_templates WHERE (code='real-company-org-test' AND id<>'wf-real-company-org-test') OR (id='wf-real-company-org-test' AND code<>'real-company-org-test')) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='测试模板编码与既有模板冲突'; END IF;
  INSERT INTO workflow_templates(id,code,active,current_version,draft_revision,draft,published,created_by)
  VALUES('wf-real-company-org-test','real-company-org-test',TRUE,0,1,v_template,NULL,v_admin_id)
  ON DUPLICATE KEY UPDATE active=TRUE,draft_revision=draft_revision+1;
  SELECT current_version+1 INTO v_template_version FROM workflow_templates WHERE id='wf-real-company-org-test' FOR UPDATE;
  INSERT INTO workflow_template_releases(template_id,version,definition,form_snapshot,published_by)
  VALUES('wf-real-company-org-test',v_template_version,v_template,JSON_EXTRACT(v_config,'$.form'),v_admin_id);
  UPDATE workflow_templates SET draft=v_template,published=v_template,current_version=v_template_version,updated_at=UTC_TIMESTAMP(3) WHERE id='wf-real-company-org-test';
  DELETE FROM activity_type_templates WHERE template_id='wf-real-company-org-test';
  INSERT INTO activity_type_templates(activity_type_id,template_id,is_default) SELECT id,'wf-real-company-org-test',FALSE FROM activity_types WHERE active=TRUE;
  INSERT INTO audit_events(id,actor_id,action,data) VALUES(UUID(),v_admin_id,'按真实公司图片重置组织架构',JSON_OBJECT('departments',27,'testAccounts',108,'backup','real-org-20261023-v1','configVersion',v_version));
  COMMIT;
END$$
CALL orgsql_rebuild_20261023()$$
DROP PROCEDURE orgsql_rebuild_20261023$$
DELIMITER ;

-- 执行成功后核对：应为27个部门、108个启用测试账号，每部门4个，负责人账号无数字。
SELECT d.id,d.parent_id,d.name,m.username AS manager_account FROM departments d LEFT JOIN members m ON m.id=d.manager_id ORDER BY d.parent_id,d.id;
SELECT department_id,COUNT(*) AS test_accounts FROM members WHERE active=TRUE AND id LIKE 'u-org-%' GROUP BY department_id;
SELECT version FROM configuration_releases ORDER BY version DESC LIMIT 1;
